from collections import deque

def find_connected_components(grid, bg):
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and not visited[r][c]:
                # BFS to find all cells with same color
                component = {}
                for color in range(1, 10):
                    component[color] = []

                queue = deque([(r, c, grid[r][c])])
                visited[r][c] = True

                while queue:
                    cr, cc, color = queue.popleft()
                    component[color].append((cr, cc))

                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if grid[nr][nc] == color and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc, color))

                for color in component:
                    if color != bg and component[color]:
                        components.append(component)

    return components

